function prepareRegistryQueries({ values }) {
  if (!Array.isArray(values)) throw new Error("Sheet values must be a matrix.");
  if (!values.length) return { jobs: [], hasJobs: false };
  const headers = values[0];
  if (
    !Array.isArray(headers) ||
    headers.some((h) => typeof h !== "string" || !h) ||
    new Set(headers).size !== headers.length
  )
    throw new Error("Use unique, contiguous text headers.");
  const key = headers.indexOf("company");
  if (key < 0) throw new Error("The sheet needs a company column.");
  const jobs = [];
  for (let i = 1; i < values.length; i++) {
    const row = values[i];
    if (!Array.isArray(row)) throw new Error("Invalid sheet row.");
    if (row.every((v) => v == null || v === "")) continue;
    const raw = row[key],
      company = typeof raw === "number" && Number.isFinite(raw) ? String(raw) : raw;
    if (typeof company !== "string" || !company.trim())
      throw new Error("Each company row needs a name or registration number.");
    jobs.push({ company });
  }
  return { jobs, hasJobs: jobs.length > 0 };
}

return [{ json: prepareRegistryQueries({ values: $input.first().json.body.values ?? [] }) }];

function collectRegistryCompanies({ jobs, previousState, startedRun, polledRun, items }) {
  const fields = {
    company: "name",
    registrationNumber: "registrationNumber",
    vatNumber: "vatNumber",
    country: "countryName",
    registry: "registry",
    status: "status",
    incorporatedAt: "incorporatedAt",
    address: "address",
    city: "city",
    website: "website",
    registryUrl: "registryUrl",
  };
  const state = previousState ?? { index: 0, records: [], stage: "new" };
  if (!Array.isArray(jobs) || !Array.isArray(state.records) || !Number.isInteger(state.index))
    throw new Error("Invalid registry collection state.");
  const finishJob = () => {
    state.index++;
    state.stage = "new";
    delete state.runId;
    delete state.datasetId;
    delete state.pollStartedAt;
    delete state.pollLimitMs;
    delete state.timeoutChecked;
    delete state.offset;
  };
  if (state.stage === "start") {
    if (!startedRun || typeof startedRun.id !== "string" || !startedRun.id)
      throw new Error("Actor start returned no run ID.");
    state.runId = startedRun.id;
    state.pollStartedAt = Date.now();
    state.pollLimitMs = 86400000;
    state.timeoutChecked = false;
    state.stage = "poll";
  } else if (state.stage === "poll") {
    if (
      !polledRun ||
      polledRun.id !== state.runId ||
      typeof polledRun.status !== "string" ||
      !polledRun.status
    )
      throw new Error("The polled Actor run does not match the started run.");
    if (["SUCCEEDED", "FAILED", "TIMED-OUT", "ABORTED"].includes(polledRun.status)) {
      if (polledRun.status !== "SUCCEEDED")
        throw new Error("Actor did not succeed: " + polledRun.status);
      if (typeof polledRun.defaultDatasetId !== "string" || !polledRun.defaultDatasetId)
        throw new Error("Successful Actor returned no dataset ID.");
      state.datasetId = polledRun.defaultDatasetId;
      state.offset = 0;
      state.stage = "items";
    } else {
      if (!state.timeoutChecked) {
        const secs = Number(polledRun.options?.timeoutSecs);
        if (Number.isFinite(secs) && secs > 0) state.pollLimitMs = secs * 1000 + 300000;
        state.timeoutChecked = true;
      }
      if (Date.now() - state.pollStartedAt > state.pollLimitMs)
        throw new Error("Timed out waiting for Actor completion.");
    }
  } else if (state.stage === "items") {
    if (!Array.isArray(items) || items.length > 1000) throw new Error("Invalid dataset page.");
    for (const item of items) {
      if (
        !item ||
        typeof item !== "object" ||
        Array.isArray(item) ||
        typeof item.name !== "string" ||
        !item.name
      )
        throw new Error("Company result needs a nonempty name.");
      const record = {};
      for (const [k, source] of Object.entries(fields)) {
        const value = item[source];
        record[k] =
          value == null ? null : typeof value === "object" ? JSON.stringify(value) : String(value);
      }
      state.records.push(record);
    }
    state.offset += items.length;
    if (items.length < 1000) finishJob();
  }
  let action = state.stage;
  if (state.stage === "new") {
    if (state.index >= jobs.length) action = "complete";
    else {
      state.stage = "start";
      action = "start";
    }
  }
  return {
    state,
    action,
    input: {
      queries: state.index < jobs.length ? [jobs[state.index].company] : [],
      countries: ["cz", "ee", "fi", "fr", "no", "pl", "sk"],
      maxResultsPerQuery: 1,
      onlyActive: true,
    },
    offset: state.offset ?? 0,
    records: state.records,
    hasRecords: state.records.length > 0,
    queryCount: jobs.length,
  };
}

const packet = $input.first().json;
return [{ json: { ...collectRegistryCompanies(packet), jobs: packet.jobs } }];

const response = $input.first().json.body,
  previous = $("Collect complete registry results").item.json;
return [
  {
    json: {
      jobs: previous.jobs,
      previousState: previous.state,
      startedRun: previous.action === "start" ? response.data : null,
      polledRun: previous.action === "poll" ? response.data : null,
      items: previous.action === "items" ? response : null,
    },
  },
];

function planRegistryWrites({ values, records, sheetName }) {
  if (
    !Array.isArray(values) ||
    !Array.isArray(records) ||
    typeof sheetName !== "string" ||
    !sheetName
  )
    throw new Error("Invalid sheet write inputs.");
  const columns = [
    "company",
    "registrationNumber",
    "vatNumber",
    "country",
    "registry",
    "status",
    "incorporatedAt",
    "address",
    "city",
    "website",
    "registryUrl",
  ];
  const headers = values[0] ?? [];
  if (headers.some((h) => typeof h !== "string" || !h) || new Set(headers).size !== headers.length)
    throw new Error("Use unique, contiguous text headers.");
  if (!headers.includes("company")) throw new Error("The target sheet needs a company column.");
  const finalHeaders = [...headers, ...columns.filter((k) => !headers.includes(k))],
    key = headers.indexOf("company"),
    sheet = "'" + sheetName.replaceAll("'", "''") + "'",
    column = (n) => {
      let s = "";
      for (n++; n; n = Math.floor((n - 1) / 26)) s = String.fromCharCode(65 + ((n - 1) % 26)) + s;
      return s;
    };
  const existing = new Map();
  for (let i = 1; i < values.length; i++) {
    const row = values[i];
    if (!Array.isArray(row)) throw new Error("Invalid target row.");
    if (row[key] != null && !existing.has(String(row[key]))) existing.set(String(row[key]), i + 1);
  }
  const headerData =
      finalHeaders.length === headers.length
        ? []
        : [
            {
              range: sheet + "!A1:" + column(finalHeaders.length - 1) + "1",
              values: [finalHeaders],
            },
          ],
    updateData = [],
    appendValues = [];
  let updatedRecords = 0;
  for (const record of records) {
    if (!record || typeof record.company !== "string" || !record.company)
      throw new Error("Company result needs a nonempty name.");
    const target = existing.get(record.company);
    if (target != null) {
      updatedRecords++;
      for (const k of columns) {
        if (k === "company" || record[k] == null) continue;
        updateData.push({
          range: sheet + "!" + column(finalHeaders.indexOf(k)) + target,
          values: [[record[k]]],
        });
      }
    } else appendValues.push(finalHeaders.map((h) => record[h] ?? ""));
  }
  return {
    headerCellsExpected: finalHeaders.length,
    updateCellsExpected: updateData.length,
    request: {
      ...(headerData.length ? { headerData } : {}),
      ...(updateData.length ? { updateData } : {}),
      ...(appendValues.length ? { appendValues } : {}),
    },
    hasHeader: headerData.length > 0,
    hasUpdates: updateData.length > 0,
    hasAppends: appendValues.length > 0,
    updatedRecords,
    appendedRecords: appendValues.length,
    companyRecords: records.length,
    appendRange: sheet + "!A1:" + column(finalHeaders.length - 1) + "1",
  };
}

const { request, ...plan } = planRegistryWrites({
  values: $input.first().json.body.values ?? [],
  records: $("Collect complete registry results").item.json.records,
  sheetName: "Companies",
});
return [{ json: { ...plan, ...request } }];

const previous = $("New registry columns needed").item.json,
  cells = $input.first().json.body.totalUpdatedCells;
if (cells !== previous.headerCellsExpected)
  throw new Error("Header write receipt does not match the request.");
return [{ json: { ...previous, headerCells: cells } }];

const previous = $("Existing company cells need updates").item.json,
  cells = $input.first().json.body.totalUpdatedCells;
if (cells !== previous.updateCellsExpected)
  throw new Error("Cell update receipt does not match the request.");
return [{ json: { ...previous, updateCells: cells } }];

const previous = $("Unmatched companies need appending").item.json,
  rows = $input.first().json.body.updates.updatedRows;
if (rows !== previous.appendedRecords)
  throw new Error("Append receipt does not match the request.");
return [{ json: { ...previous, appendRows: rows } }];

function registryReceipt({
  queryCount,
  companyRecords,
  updatedRecords,
  appendedRecords,
  hasHeader,
  hasUpdates,
  hasAppends,
  headerCellsExpected,
  updateCellsExpected,
  headerCells,
  updateCells,
  appendRows,
}) {
  if (companyRecords == null)
    return { queries: queryCount, companyRecords: 0, rowsUpdated: 0, rowsAppended: 0 };
  if (hasHeader && headerCells !== headerCellsExpected)
    throw new Error("Header write receipt does not match the request.");
  if (hasUpdates && updateCells !== updateCellsExpected)
    throw new Error("Cell update receipt does not match the request.");
  if (hasAppends && appendRows !== appendedRecords)
    throw new Error("Append receipt does not match the request.");
  return {
    queries: queryCount,
    companyRecords,
    rowsUpdated: updatedRecords,
    rowsAppended: appendedRecords,
  };
}

const packet = $input.first().json;
return [
  {
    json: registryReceipt({
      ...packet,
      queryCount: $("Prepare every company query").first().json.jobs.length,
      headerCells: packet.headerCells,
      updateCells: packet.updateCells,
      appendRows: packet.appendRows,
    }),
  },
];
